// --- zulkitabat_clean_and_verify_module.js ---
  // ================= MODULE 15: ZUL-KITABAT QURAN SYMBOL CLEANER + AWFAQ/ZUL-KITABAT CHAAL & MEEZAN VERIFIER =================
  function stripQuranicSignsForNaqsh(str) {
    var s = String(str || '').trim();
    // 1. Strip external Quran app headers like "القرآن - سورہ نمبر 2 البقرہ آیت نمبر 2" or "سورۃ البقرہ (آیت 2)"
    s = s.replace(/^(?:القرآن|قرآنِ?\s*کریم|قرآن\s*مجید)?\s*[-—:]*\s*(?:سور[ہۃةت])\s*(?:نمبر)?\s*[0-9٠-٩۰-۹]*\s*[\u0600-\u06FF]*\s*(?:آی[تة]|آیت|ای[تة])\s*(?:نمبر)?\s*[0-9٠-٩۰-۹:\-]*\s*[-—:]*/u, '');
    s = s.replace(/(?:القرآن|سور[ہۃةت]|آی[تة]|نمبر)\s*[-—:]*\s*[0-9٠-٩۰-۹]*/gu, ' ');
    // 2. Strip leading Ta'awwuz (أعوذ بالله من الشيطان الرجيم) with or without diacritics
    s = s.replace(/^\s*[أإاآ][\u064B-\u065F\u0670]*ع[\u064B-\u065F\u0670]*و[\u064B-\u065F\u0670]*ذ[\u064B-\u065F\u0670]*\s+ب[\u064B-\u065F\u0670]*ا[\u064B-\u065F\u0670]*ل[\u064B-\u065F\u0670]*ل[\u064B-\u065F\u0670]*[هہ][\u064B-\u065F\u0670]*\s+م[\u064B-\u065F\u0670]*ن[\u064B-\u065F\u0670]*\s+ا[\u064B-\u065F\u0670]*ل[\u064B-\u065F\u0670]*ش[\u064B-\u065F\u0670]*[يی][\u064B-\u065F\u0670]*ط[\u064B-\u065F\u0670]*[اٰ]*ن[\u064B-\u065F\u0670]*\s+ا[\u064B-\u065F\u0670]*ل[\u064B-\u065F\u0670]*ر[\u064B-\u065F\u0670]*ج[\u064B-\u065F\u0670]*[يی][\u064B-\u065F\u0670]*م[\u064B-\u065F\u0670]*\s*/u, '');
    // 3. Strip leading Bismillah ONLY if more Quranic text follows it (keep Bismillah if user entered Bismillah alone!)
    var withoutBis = s.replace(/^\s*ب[\u064B-\u065F\u0670]*س[\u064B-\u065F\u0670]*م[\u064B-\u065F\u0670]*\s+ا[\u064B-\u065F\u0670]*ل[\u064B-\u065F\u0670]*ل[\u064B-\u065F\u0670]*[هہ][\u064B-\u065F\u0670]*\s+ا[\u064B-\u065F\u0670]*ل[\u064B-\u065F\u0670]*ر[\u064B-\u065F\u0670]*ح[\u064B-\u065F\u0670]*م[\u064B-\u065F\u0670]*[اٰ]*ن[\u064B-\u065F\u0670]*\s+ا[\u064B-\u065F\u0670]*ل[\u064B-\u065F\u0670]*ر[\u064B-\u065F\u0670]*ح[\u064B-\u065F\u0670]*[يی][\u064B-\u065F\u0670]*م[\u064B-\u065F\u0670]*\s+/u, '');
    if (withoutBis.trim().length >= 6) s = withoutBis;
    // 4. Strip Quranic waqf marks, parentheses, numbers, dashes & extra spaces
    return s
      .replace(/[\u06D6-\u06ED\u06DD\u06DE\u06E9\uFD3E\uFD3F﴿﴾۞۩۝\(\)\[\]\-—:]/g, ' ')
      .replace(/[0-9٠-٩۰-۹]+/g, ' ')
      .replace(/\s+/g, ' ')
      .trim();
  }

