  function appendNaqshVerificationPanel(outEl, mode, chaalLbl) {
    if (!outEl) return;
    var tbl = outEl.querySelector('#activeGeneratedNaqshBox table');
    if (!tbl) return;
    var rows = Array.prototype.map.call(tbl.querySelectorAll('tr'), function(tr) {
      return Array.prototype.map.call(tr.querySelectorAll('td'), function(td) { return (td.textContent || '').trim(); });
    });
    if (!rows.length) return;
    var n = rows.length;
    var isNumeric = rows.every(function(r) { return r.every(function(c) { return /^\d+$/.test(c); }); });

    var html = '';
    if (isNumeric) {
      var rowSums = rows.map(function(r) { return r.reduce(function(a, b) { return a + parseInt(b, 10); }, 0); });
      var colSums = [];
      for (var c = 0; c < n; c++) {
        var cs = 0;
        for (var r = 0; r < n; r++) cs += parseInt(rows[r][c] || '0', 10);
        colSums.push(cs);
      }
      var d1 = 0, d2 = 0;
      for (var i = 0; i < n; i++) {
        d1 += parseInt(rows[i][i] || '0', 10);
        d2 += parseInt(rows[i][n - 1 - i] || '0', 10);
      }
      var target = rowSums[0];
      var allEq = rowSums.every(function(x){ return x === target; }) && colSums.every(function(x){ return x === target; }) && d1 === target && d2 === target;
      html =
        '<div style="font-weight:800; color:' + (allEq ? '#065f46' : '#b45309') + '; margin-bottom:4px;">' +
          (allEq ? '✅ میزان اور چال کی تصدیق: ۱۰۰٪ درست (' + chaalLbl + ')' : '⚠️ میزان کی تفصیل (' + chaalLbl + ')') +
        '</div>' +
        '<div style="font-size:0.82rem; color:#334155; line-height:1.8;" dir="rtl">' +
          '• افقی سطروں کا مجموعہ: <b dir="ltr">' + rowSums.join(' , ') + '</b><br>' +
          '• عمودی کالموں کا مجموعہ: <b dir="ltr">' + colSums.join(' , ') + '</b><br>' +
          '• دونوں وتروں (Diagonals) کا مجموعہ: <b dir="ltr">' + d1 + ' , ' + d2 + '</b>' +
        '</div>';
    } else {
      // Zul-Kitabat Latin-Square verification: every row & every column must contain all unique segments once!
      var rowOk = rows.every(function(r) {
        var u = {}; r.forEach(function(x){ u[x] = 1; }); return Object.keys(u).length === r.length;
      });
      var colOk = true;
      for (var cc = 0; cc < n; cc++) {
        var uc = {};
        for (var rr = 0; rr < n; rr++) uc[rows[rr][cc]] = 1;
        if (Object.keys(uc).length !== n) colOk = false;
      }
      var okAll = rowOk && colOk;
      html =
        '<div style="font-weight:800; color:' + (okAll ? '#065f46' : '#b45309') + '; margin-bottom:4px;">' +
          (okAll ? '✅ ذوالکتابت میزان و چال کی تصدیق: ۱۰۰٪ درست (' + chaalLbl + ')' : '⚠️ ذوالکتابت ترتیب چیک کریں') +
        '</div>' +
        '<div style="font-size:0.82rem; color:#334155; line-height:1.8;">' +
          '• ہر افقی سطر میں مکمل آیت کے چاروں اجزاء بغیر تکرار موجود ہیں: <b>' + (rowOk ? 'جی ہاں ✅' : 'تکرار موجود') + '</b><br>' +
          '• ہر عمودی کالم میں مکمل آیت کے چاروں اجزاء بغیر تکرار موجود ہیں: <b>' + (colOk ? 'جی ہاں ✅' : 'تکرار موجود') + '</b><br>' +
          '• قرآنی علامات (۞ ۝ ۩ وغیرہ) نقش کے خانوں سے مکمل صاف کر دی گئی ہیں (یہ باکس A4 پرنٹ میں نہیں آئے گا)۔' +
        '</div>';
    }

    var vBox = document.createElement('div');
    vBox.id = 'naqshVerificationBoxB23';
    vBox.style.cssText = 'margin-top:10px; padding:9px 11px; background:#f0fdf4; border:1.5px solid #86efac; border-right:4px solid #065f46; border-radius:10px; text-align:right;';
    vBox.innerHTML = html;
    outEl.appendChild(vBox);
  }

