    badi:   [[14,1,8,11],[7,12,13,2],[9,6,3,16],[4,15,10,5]], // بادی (صفحہ ۵۱)
    aabi:   [[11,8,1,14],[2,13,12,7],[16,3,6,9],[5,10,15,4]], // آبی (صفحہ ۵۱)
