  // Point #8: Full Aamil-e-Kamil Vol 2 (pp. 136-157) Universal Tarh N*(N^2-1)/2 & Kasr House N^2 - r*N + 1 for N=3..10 (مثلث تا معشر)!
  function buildGenericMagicBase(N) {
    if (N === 3) return AAMIL_KAMIL_CHAALS_3.atishi;
    if (N === 4) return AAMIL_KAMIL_CHAALS_4.atishi;
    if (N === 5) return AAMIL_KAMIL_CHAAL_5_BASE;
    if (N % 2 === 1) {
      // Siamese odd magic square (7x7 مسبع, 9x9 متسع)
      var m = Array.from({length: N}, function(){ return Array(N).fill(0); });
      var r = 0, c = Math.floor(N / 2);
      for (var v = 1; v <= N * N; v++) {
        m[r][c] = v;
        var nr = (r - 1 + N) % N, nc = (c + 1) % N;
        if (m[nr][nc]) r = (r + 1) % N;
        else { r = nr; c = nc; }
      }
      return m;
    }
    if (N % 4 === 0) {
      // Doubly-even magic square (8x8 مثمن)
      var m8 = Array.from({length: N}, function(){ return Array(N).fill(0); });
      var v8 = 1;
      for (var i = 0; i < N; i++) {
        for (var j = 0; j < N; j++) {
          var inDiag = (i % 4 === j % 4) || ((i % 4) + (j % 4) === 3);
          m8[i][j] = inDiag ? v8 : (N * N + 1 - v8);
          v8++;
        }
      }
      return m8;
    }
    // Singly-even (6x6 مسدس from Aamil-e-Kamil Vol 2 p.136 shape #1, 10x10 معشر via Strachey)
    if (N === 6) {
      return [
        [1,35,34,3,32,6],
        [30,8,28,27,11,7],
        [24,23,15,16,14,19],
        [13,17,21,22,20,18],
        [12,26,9,10,29,25],
        [31,2,4,33,5,36]
      ];
    }
    // 10x10 Strachey
    var half = N / 2, sub = buildGenericMagicBase(half), sq = half * half;
    var m10 = Array.from({length: N}, function(){ return Array(N).fill(0); });
    for (var ri = 0; ri < half; ri++) {
      for (var ci = 0; ci < half; ci++) {
        var b = sub[ri][ci];
        m10[ri][ci] = b;
        m10[ri + half][ci + half] = b + sq;
        m10[ri][ci + half] = b + 2 * sq;
        m10[ri + half][ci] = b + 3 * sq;
      }
    }
    var k = (half - 1) / 2;
    for (var r2 = 0; r2 < half; r2++) {
      for (var c2 = 0; c2 < k; c2++) {
        var tmp = m10[r2][c2]; m10[r2][c2] = m10[r2 + half][c2]; m10[r2 + half][c2] = tmp;
      }
      for (var c3 = N - k + 1; c3 < N; c3++) {
        var tmp2 = m10[r2][c3]; m10[r2][c3] = m10[r2 + half][c3]; m10[r2 + half][c3] = tmp2;
      }
    }
    var mid = Math.floor(half / 2);
    var tA = m10[mid][0]; m10[mid][0] = m10[mid + half][0]; m10[mid + half][0] = tA;
    var tB = m10[mid][mid]; m10[mid][mid] = m10[mid + half][mid]; m10[mid + half][mid] = tB;
    return m10;
  }

  // Upgrade buildAamilKamilAuthenticNumericNaqsh to handle N=3..10 seamlessly!
  buildAamilKamilAuthenticNumericNaqsh = function(totalNum, order, chaalKey) {
    var N = Math.max(3, Math.min(10, parseInt(order, 10) || 3));
    var tarh = (N * (N * N - 1)) / 2;
    var remBase = totalNum - tarh;
    if (remBase < N) remBase = N;
    var q = Math.floor(remBase / N);
    var kasr = remBase % N;
    var kasrHouse = (kasr > 0) ? (N * N - kasr * N + 1) : 9999;

    var mat = (N === 3) ? (AAMIL_KAMIL_CHAALS_3[chaalKey] || AAMIL_KAMIL_CHAALS_3.atishi)
            : (N === 4) ? (AAMIL_KAMIL_CHAALS_4[chaalKey] || AAMIL_KAMIL_CHAALS_4.atishi)
            : buildGenericMagicBase(N);
    if (N >= 5 && typeof applyChaalTransform === 'function' && chaalKey !== 'atishi') {
      mat = applyChaalTransform(mat, chaalKey);
    }
    var filled = mat.map(function(row) {
      return row.map(function(pos) { return q + (pos - 1) + (pos >= kasrHouse ? 1 : 0); });
    });
    return { matrix: filled, tarh: tarh, base: q, kasr: kasr, kasrHouse: kasr > 0 ? kasrHouse : 0 };
  };

