  // Authentic Kash Al-Barni Zul-Kitabat whole-word segmentation (NEVER chops a word in half!)
  function splitIntoBalancedSegmentsV34(cleanText, n){
    var words = cleanText.split(/\s+/).filter(Boolean);
    if (!words.length) return [];
    // If fewer words than grid size n, split cleanly into individual letters (ذوالکتابت حرفی)
    if (words.length < n) {
      var letters = cleanText.replace(/[\s\u064B-\u065F\u0670\u06D6-\u06ED]/g, '').split('').filter(Boolean);
      if (letters.length >= n) {
        var lSegs = [];
        var lSize = Math.ceil(letters.length / n);
        for (var li = 0; li < n; li++) {
          lSegs.push(letters.slice(li * lSize, (li + 1) * lSize).join(' ') || letters[li % letters.length]);
        }
        return lSegs;
      }
      var pad = [];
      for (var pi = 0; pi < n; pi++) pad.push(words[pi % words.length]);
      return pad;
    }
    // Distribute whole words evenly across n segments
    var segs = [];
    var base = Math.floor(words.length / n);
    var rem = words.length % n;
    var cur = 0;
    for (var i = 0; i < n; i++) {
      var take = base + (i < rem ? 1 : 0);
      segs.push(words.slice(cur, cur + take).join(' '));
      cur += take;
    }
    return segs;
  }

